export const MODELS={NM22:{name:'NM-22',line:1,label:'Línea 1',description:'Modelo visual de la Línea 1, con interior y equipos revisados a partir de tus fotografías.'},NM79:{name:'NM-79',line:8,label:'Línea 8',description:'Modelo neumático con interior, puertas y equipos de la Línea 8.'},MP82:{name:'MP-82',line:8,label:'Línea 8',description:'Cabecera e intermedio reconstruidos a partir de las referencias que aportaste.'}};
export const PARTS={collectors:{name:'Captación de corriente',function:'Escobillas positivas entre las ruedas de cada bogie motriz: toman corriente de la barra guía. Se representan soporte, aisladores, brazo de presión, portaescobilla, patín de carbón, cable y protección exterior en U. Dos por bogie y cuatro por coche motriz como referencia general; montaje y medidas aproximados.',maintenance:'Inspección visual didáctica. Las escobillas de retorno y de maza son elementos distintos. No se representa un mecanismo de interruptor ni una conexión de mantenimiento real.',offset:[0,-.4,3.5]},locks:{name:'Cerraduras entre coches · L8',function:'Placa cromada, manija, tornillos, cerradero y alojamiento triangular observados en las fotografías aportadas de Línea 8. Se ubican en las puertas de comunicación de los testeros.',maintenance:'Representación visual con dimensiones aproximadas. No se reproduce el mecanismo interno ni se supone que corresponda a Línea 1.',offset:[0,1.1,2.8]},motors:{name:'Motores de tracción',function:'Convierten energía eléctrica en par que se transmite a los ejes de rodadura. Se muestran dos motores por bogie y cuatro por coche motriz como referencia general del STC. Carcasa, estator, rotor, eje y transmisión son aproximaciones didácticas.',maintenance:'Identifica carcasa, conexiones, soportes y rodamientos. El ensayo visual permite cortar alimentación y aislar el motor; no sustituye pruebas, valores ni procedimientos de fabricante.',offset:[0,-1.1,3.8]},body:{name:'Carrocería y ventanas',function:'Forma el espacio del coche y protege a los ocupantes. Las ventanas permiten observar el exterior.',maintenance:'La práctica permite observar paneles, ventanas y uniones. No representa ensayos estructurales.',offset:[0,0,3.4]},doors:{name:'Puertas de pasajeros',function:'Controlan el acceso entre el andén y el coche. El movimiento real depende del mecanismo y del control de cada modelo.',maintenance:'En el ejercicio se comprueba un obstáculo virtual y el cierre. El mecanismo interno no está completamente documentado.',offset:[0,.35,5.8]},interior:{name:'Interior y mobiliario',function:'Incluye asientos, pasamanos, luminarias y elementos visibles de servicio a pasajeros.',maintenance:'La selección permite estudiar los elementos existentes; las comprobaciones de funcionamiento son simuladas.',offset:[0,2.0,0]},roof:{name:'Cubierta y ventilación',function:'Cierra la parte superior del coche y agrupa elementos visibles de iluminación o ventilación del modelo.',maintenance:'La ubicación y disposición de equipos se aproximan a las fotografías; no se presupone el mismo circuito para los tres modelos.',offset:[0,4.6,0]},mechanics:{name:'Rodaje y bajos',function:'Conjunto visual de ruedas, bogies y equipos bajo el coche. El bogie soporta y guía el vehículo; los equipos de tracción producen el movimiento.',maintenance:'Los bajos contienen geometría de referencia compartida y aproximada. No constituyen un despiece de fabricante.',offset:[0,-2.5,0]},cab:{name:'Cabina de conducción',function:'Espacio de mando del operador. En el modo de conducción puedes accionar tracción, freno y puertas.',maintenance:'Los mandos del simulador son didácticos y aún no reproducen el pupitre real ni sus circuitos.',offset:[-5.2,.5,0]}};
export function partCategory(name,family='') {if(name.startsWith('Captador_'))return'collectors';if(family==='lock92')return'locks';if(family==='traction')return'motors';if(family.startsWith('Puerta_S')||/^Puerta_S/.test(name))return'doors';if(family==='cab')return'cab';if(family==='mecanica')return'mechanics';if(family==='roof')return'roof';if(family.startsWith('interior'))return'interior';return'body';}
export const CASES={doors:{title:'Puerta con obstáculo virtual',group:'doors',diagnosis:'La comprobación detectó un obstáculo en el recorrido de una puerta.',repair:'Retirar obstáculo virtual'},ventilation:{title:'Ventilación sin respuesta',group:'roof',diagnosis:'El equipo de ventilación del ejercicio no responde al mando simulado.',repair:'Restablecer equipo simulado'},running:{title:'Incidencia en rodaje',group:'mechanics',diagnosis:'Se registró una incidencia visual de prueba en el conjunto de rodaje.',repair:'Corregir incidencia virtual'}};
export class MaintenanceExercise{
 constructor(){this.reset('doors');}
 reset(id){this.id=id;this.isolated=false;this.inspected=false;this.repaired=false;this.passed=false;this.log=[];}
 isolate(){this.isolated=true;this.log.push('Alimentación del ejercicio aislada.');return'Equipo aislado para esta práctica.';}
 inspect(group){if(!this.isolated)throw Error('Aísla primero la alimentación simulada.');if(group!==CASES[this.id].group)throw Error('Selecciona el conjunto indicado para esta incidencia.');this.inspected=true;this.log.push('Inspección completada.');return CASES[this.id].diagnosis;}
 repair(){if(!this.isolated||!this.inspected)throw Error('Completa el aislamiento y la inspección antes de corregir.');this.repaired=true;this.log.push('Corrección virtual aplicada.');return'Corrección aplicada. Ejecuta la comprobación final.';}
 test(){if(!this.repaired)throw Error('La incidencia aún no se ha corregido.');this.passed=true;this.log.push('Comprobación del ejercicio: correcta.');return'Práctica completada: la comprobación simulada es correcta.';}
}
